export function wordsForLength(len) {
  return WORDS_BY_LENGTH[len] || [];
}

export function pickRandomWord(len) {
  const list = wordsForLength(len);
  if (!list.length) return null;
  return list[Math.floor(Math.random() * list.length)];
}
